"""Test the real early frame allocator against an independent ownership model."""

import ctypes
import importlib.util
import pathlib
import random
import subprocess
import sys
import tempfile
import unittest

PROJECT_ROOT = pathlib.Path(__file__).resolve().parents[1]
# Fixture imports must not leave generated bytecode in the source tree.
sys.dont_write_bytecode = True
FIXTURE_SPEC = importlib.util.spec_from_file_location(
    "boot_memory_fixtures", PROJECT_ROOT / "util/test-boot-memory.py")
FIXTURES = importlib.util.module_from_spec(FIXTURE_SPEC)
FIXTURE_SPEC.loader.exec_module(FIXTURES)


class FrameAllocator(ctypes.Structure):
    """Mirror the caller-owned C allocator state for native checks."""

    _fields_ = [("spans", FIXTURES.MemoryRange * 64), ("span_count", ctypes.c_uint),
                ("bitmap", ctypes.c_void_p), ("bitmap_bytes", ctypes.c_size_t),
                ("total_frames", ctypes.c_ulong), ("free_frames", ctypes.c_ulong),
                ("initialized", ctypes.c_bool)]


class FrameAllocatorTests(unittest.TestCase):
    """Check ownership, fragmentation, holes, exhaustion, and invalid releases."""

    @classmethod
    def setUpClass(cls):
        """Compile the production allocator as a disposable native library."""
        cls.temporary_directory = tempfile.TemporaryDirectory(prefix="aether-frames-")
        library_path = pathlib.Path(cls.temporary_directory.name) / "frames.so"
        subprocess.run([
            "clang", "-shared", "-fPIC", "-Wall", "-Wextra", "-Werror",
            f"-I{PROJECT_ROOT / 'kernel/include'}", str(PROJECT_ROOT / "kernel/boot/frames.c"),
            "-o", str(library_path),
        ], check=True)
        cls.library = ctypes.CDLL(str(library_path))
        cls.library.frame_allocator_metadata_size.argtypes = [ctypes.POINTER(FIXTURES.MemoryMap)]
        cls.library.frame_allocator_metadata_size.restype = ctypes.c_size_t
        cls.library.frame_allocator_initialize.argtypes = [ctypes.POINTER(FrameAllocator),
            ctypes.POINTER(FIXTURES.MemoryMap), ctypes.c_void_p, ctypes.c_size_t]
        cls.library.frame_allocator_initialize.restype = ctypes.c_bool
        cls.library.frame_allocator_allocate.argtypes = [ctypes.POINTER(FrameAllocator),
            ctypes.c_ulong, ctypes.POINTER(ctypes.c_ulong)]
        cls.library.frame_allocator_allocate.restype = ctypes.c_bool
        cls.library.frame_allocator_release.argtypes = [ctypes.POINTER(FrameAllocator),
            ctypes.c_ulong, ctypes.c_ulong]
        cls.library.frame_allocator_release.restype = ctypes.c_bool

    @classmethod
    def tearDownClass(cls):
        """Remove all temporary compilation artifacts."""
        cls.temporary_directory.cleanup()

    def initialize(self, spans=((0x1000, 0x4000), (0x10000, 0x13000))):
        """Provide reserved host storage separate from the synthetic physical spans."""
        memory_map = FIXTURES.MemoryMap()
        memory_map.available_count = len(spans)
        for span_index, (base, end) in enumerate(spans):
            memory_map.available[span_index].base = base
            memory_map.available[span_index].end = end
        storage_bytes = self.library.frame_allocator_metadata_size(ctypes.byref(memory_map))
        bitmap_storage = ctypes.create_string_buffer(bytes([0xa5]) * (storage_bytes + 16))
        allocator = FrameAllocator()
        self.assertTrue(self.library.frame_allocator_initialize(
            ctypes.byref(allocator), ctypes.byref(memory_map), bitmap_storage, storage_bytes))
        return allocator, bitmap_storage

    def allocate(self, allocator, count):
        """Require deterministic zero results whenever an allocation fails."""
        result = ctypes.c_ulong(0xdeadbeef)
        accepted = self.library.frame_allocator_allocate(ctypes.byref(allocator), count,
                                                          ctypes.byref(result))
        if not accepted:
            self.assertEqual(result.value, 0)
        return result.value

    def release(self, allocator, address, count):
        """Call the fallible release API without adding host-side ownership rules."""
        return self.library.frame_allocator_release(ctypes.byref(allocator), address, count)

    def test_exhaustion_and_reuse(self):
        """Each usable frame is issued once; holes never become allocations."""
        allocator, bitmap_storage = self.initialize()
        issued_frames = [self.allocate(allocator, 1) for frame_index in range(6)]
        self.assertEqual(issued_frames, [0x1000, 0x2000, 0x3000, 0x10000, 0x11000, 0x12000])
        self.assertEqual(self.allocate(allocator, 1), 0)
        self.assertEqual(allocator.free_frames, 0)
        self.assertTrue(self.release(allocator, 0x2000, 1))
        self.assertEqual(self.allocate(allocator, 1), 0x2000)
        self.assertEqual(bytes(bitmap_storage)[allocator.bitmap_bytes:allocator.bitmap_bytes + 16],
                         bytes([0xa5]) * 16)

    def test_contiguous_requests_do_not_cross_holes(self):
        """Total free capacity does not imply a contiguous physical allocation."""
        allocator, bitmap_storage = self.initialize()
        self.assertEqual(self.allocate(allocator, 4), 0)
        self.assertEqual(allocator.free_frames, 6)
        self.assertEqual(self.allocate(allocator, 3), 0x1000)
        self.assertEqual(self.allocate(allocator, 3), 0x10000)
        self.assertFalse(self.release(allocator, 0x3000, 2))
        self.assertEqual(allocator.free_frames, 0)

    def test_invalid_releases_are_atomic(self):
        """An invalid range cannot partially free live frames or reservations."""
        allocator, bitmap_storage = self.initialize()
        self.assertEqual(self.allocate(allocator, 2), 0x1000)
        original_bitmap = bytes(bitmap_storage)
        for base, count in ((0, 1), (0x1001, 1), (0x1000, 3), (0x4000, 1),
                            (0x1000, 0), (0x1000, 2**64 - 1)):
            self.assertFalse(self.release(allocator, base, count))
            self.assertEqual(bytes(bitmap_storage), original_bitmap)
            self.assertEqual(allocator.free_frames, 4)
        self.assertTrue(self.release(allocator, 0x1000, 2))
        self.assertFalse(self.release(allocator, 0x1000, 2))
        self.assertEqual(allocator.free_frames, 6)

    def test_metadata_and_invalid_maps(self):
        """Initialization rejects unsorted, overlapping, unaligned, or empty spans."""
        for spans in ((), ((0, 4096),), ((0x1001, 0x2000),),
                      ((0x1000, 0x2001),), ((0x1000, 0x1000),),
                      ((0x2000, 0x4000), (0x1000, 0x2000)),
                      ((0x1000, 0x3000), (0x2000, 0x4000))):
            memory_map = FIXTURES.MemoryMap()
            memory_map.available_count = len(spans)
            for span_index, (base, end) in enumerate(spans):
                memory_map.available[span_index].base = base
                memory_map.available[span_index].end = end
            self.assertEqual(self.library.frame_allocator_metadata_size(ctypes.byref(memory_map)), 0)
            allocator = FrameAllocator()
            storage = ctypes.create_string_buffer(16)
            self.assertFalse(self.library.frame_allocator_initialize(
                ctypes.byref(allocator), ctypes.byref(memory_map), storage, len(storage)))
            self.assertFalse(allocator.initialized)
        memory_map = FIXTURES.MemoryMap()
        memory_map.available_count = 1
        memory_map.available[0].base, memory_map.available[0].end = 0x1000, 0xb000
        self.assertEqual(self.library.frame_allocator_metadata_size(ctypes.byref(memory_map)), 2)
        allocator = FrameAllocator()
        storage = ctypes.create_string_buffer(1)
        self.assertFalse(self.library.frame_allocator_initialize(
            ctypes.byref(allocator), ctypes.byref(memory_map), storage, 1))
        self.assertEqual(self.allocate(allocator, 1), 0)

    def test_randomized_ownership_model(self):
        """Compare fragmentation and accounting with an independent page-set model."""
        spans = ((0x1000, 0x21000), (0x80000, 0x91000))
        allocator, bitmap_storage = self.initialize(spans)
        random_source = random.Random(20261031)
        active_allocations = []
        owned_pages = set()
        for operation_index in range(400):
            if active_allocations and random_source.random() < 0.45:
                allocation_index = random_source.randrange(len(active_allocations))
                base, count = active_allocations.pop(allocation_index)
                self.assertTrue(self.release(allocator, base, count))
                owned_pages.difference_update(range(base, base + count * 4096, 4096))
            else:
                count = random_source.randrange(1, 7)
                expected_base = 0
                for span_base, span_end in spans:
                    for candidate in range(span_base, span_end - count * 4096 + 1, 4096):
                        if all(page not in owned_pages for page in
                               range(candidate, candidate + count * 4096, 4096)):
                            expected_base = candidate
                            break
                    if expected_base:
                        break
                result = self.allocate(allocator, count)
                self.assertEqual(result, expected_base)
                if result:
                    active_allocations.append((result, count))
                    owned_pages.update(range(result, result + count * 4096, 4096))
            self.assertEqual(allocator.free_frames, allocator.total_frames - len(owned_pages))
        self.assertEqual(bytes(bitmap_storage)[allocator.bitmap_bytes:allocator.bitmap_bytes + 16],
                         bytes([0xa5]) * 16)


if __name__ == "__main__":
    unittest.main(verbosity=2)
